config.script:
try:
	system.perspective.closePopup('Tree Selector')
except:
	pass

self.custom.setPath = False		

return


if self.view.params.values is None or not self.view.params.values.has_key('data') or self.view.params.values['data'] is None:
	system.kanoa.toast.show({'type': 'info', 'message': 'Selector still initializing...'})
else:
	values = dict(self.view.custom.params)
	values['selectorId'] = self.view.custom.selectorId
	payload = {'values': values}
	system.perspective.openPopup("Tree Selector", "kanoa/core/templates/selectors/tree/treePopup", params=payload, overlayDismiss=True, resizable=True, viewportBound=True, showCloseIcon=True)

return

transforms.code:
options = value['options'] or {}
#The selected path in the session's language when the tree shows translated names (e.g. dashboards)
translate = bool(options['translate']) if hasattr(options, 'has_key') and options.has_key('translate') else False
return system.kanoa.utilities.formatPath(value['display'], {'locale': value['locale']} if translate else {})

import re

#A plain property binding, not a struct: a struct binding can keep a stale run with no data as the view opens, which leaves the breadcrumb empty
try: treePath = self.view.params.values['treePath']
except: treePath = None
treePath = str(treePath or 'path')
rows = system.kanoa.utilities.convertDatasetToDict(value, treePath, None) if value is not None else {}
nodes = {}
roots = []

for key in rows.keys():
	if not key: continue
	sections = key.split("\\")
	for i, section in enumerate(sections):
		path = "\\".join(sections[:i+1])
		if nodes.has_key(path): continue
		if rows.has_key(path): data = dict(rows[path])
		else:	#Intermediate node that isn't in the dataset
			data = dict((k, None) for k in rows[key].keys())
			data[treePath] = path
		nodes[path] = {'id': path, 'label': section, 'data': data, 'children': []}
		if i == 0: roots.append(nodes[path])
		else: nodes["\\".join(sections[:i])]['children'].append(nodes[path])

def naturalLabelKey(s):
	return tuple((0, int(part)) if part.isdigit() else (1, part) for part in re.findall(r'\d+|[^\d]+', (s or '').strip().lower()))

def sortKey(node):
	sortOrder = node['data'].get('sortOrder')
	return (sortOrder is None, sortOrder if sortOrder is not None else 0, naturalLabelKey(node['label']))

def sortNodes(level):
	level.sort(key=sortKey)
	for node in level: sortNodes(node['children'])

sortNodes(roots)
return roots

